#!/usr/bin/env -S deno run --allow-read --allow-write
/**
 * build-skills.ts
 *
 * Reads all skill .md files and generates _skills.generated.ts,
 * which embeds them as string constants. Run before deploying:
 *
 *   deno run --allow-read --allow-write supabase/functions/editor-chat/build-skills.ts
 *
 * The generated file is imported by index.ts so Supabase edge functions
 * get the skill content without needing Deno.readTextFile at runtime.
 */

import { dirname, fromFileUrl, join } from "https://deno.land/std@0.168.0/path/mod.ts";

const __dirname = dirname(fromFileUrl(import.meta.url));

const REMOTION_RULES = [
  "animations",
  "videos",
  "audio",
  "sequencing",
  "transitions",
  "timing",
  "assets",
  "text-animations",
  "compositions",
];

const skillsMap: Record<string, string> = {};

for (const rule of REMOTION_RULES) {
  const path = join(__dirname, "skills", "remotion", `${rule}.md`);
  skillsMap[`remotion/${rule}`] = await Deno.readTextFile(path);
  console.log(`  read remotion/${rule}.md (${skillsMap[`remotion/${rule}`].length} chars)`);
}

const catalogPath = join(__dirname, "skills", "compositions", "CATALOG.md");
skillsMap["compositions/CATALOG"] = await Deno.readTextFile(catalogPath);
console.log(`  read compositions/CATALOG.md (${skillsMap["compositions/CATALOG"].length} chars)`);

// Generate the TypeScript file
const lines = [
  "// AUTO-GENERATED by build-skills.ts — do not edit manually",
  "// Run: deno run --allow-read --allow-write supabase/functions/editor-chat/build-skills.ts",
  "",
  "export const SKILLS_MAP: Record<string, string> = {",
];

for (const [key, content] of Object.entries(skillsMap)) {
  // Escape backticks and ${ in the content
  const escaped = content.replace(/\\/g, "\\\\").replace(/`/g, "\\`").replace(/\$\{/g, "\\${");
  lines.push(`  ${JSON.stringify(key)}: \`${escaped}\`,`);
  lines.push("");
}

lines.push("};");
lines.push("");

const output = lines.join("\n");
const outPath = join(__dirname, "_skills.generated.ts");
await Deno.writeTextFile(outPath, output);
console.log(`\nGenerated ${outPath} (${output.length} chars)`);
